/*  Alter View in target  */

ALTER ALGORITHM=UNDEFINED DEFINER=`thedba`@`%` SQL SECURITY DEFINER VIEW `BillingRequestExplorers` AS select `b`.`Id` AS `Id`,`b`.`Uid` AS `Uid`,`e`.`Uid` AS `EngagementUid`,`e`.`Description` AS `EngagementDescription`,`c`.`TenantCode` AS `TenantCode`,`c`.`Uid` AS `ClientUid`,`c`.`Name` AS `ClientName`,`u`.`Uid` AS `ResourceUid`,concat(`u`.`FirstName`,' ',`u`.`LastName`) AS `ResourceName`,`b`.`PeriodThru` AS `PeriodThru`,`b`.`ServicesDescription` AS `ServicesDescription`,`b`.`ServicesAmount` AS `ServicesAmount`,`b`.`ExpensesDescription` AS `ExpensesDescription`,`b`.`ExpensesAmount` AS `ExpensesAmount`,`b`.`ReadyToInvoice` AS `ReadyToInvoice`,`b`.`ProcessCode` AS `ProcessCode`,`b`.`ProcessMessage` AS `ProcessMessage`,`b`.`InvoiceDate` AS `InvoiceDate`,`b`.`ExternalInvoiceId` AS `ExternalInvoiceId`,`b`.`ExternalInvoiceDocNum` AS `ExternalInvoiceDocNum`,(`b`.`InvoiceDate` > '1883-11-19 00:00:00') AS `Invoiced`,if((`b`.`InvoiceDate` > '1883-11-19 00:00:00'),cast(year(`b`.`InvoiceDate`) as char(4) charset utf8mb3),'') AS `InvoiceYear`,if((`b`.`InvoiceDate` > '1883-11-19 00:00:00'),cast(month(`b`.`InvoiceDate`) as char(2) charset utf8mb3),'') AS `InvoiceMonth`,`b`.`PaidDate` AS `PaidDate`,coalesce((select concat(`ud`.`LastName`,', ',`ud`.`FirstName`) from (`EngagementResources` `erd` join `Users` `ud` on((`ud`.`Id` = `erd`.`ResourceId`))) where ((`erd`.`ParentId` = `e`.`Id`) and (`erd`.`RoleCode` = 'Deal AMP')) limit 1),'') AS `DealAmp`,coalesce((select concat(`uh`.`LastName`,', ',`uh`.`FirstName`) from (`EngagementResources` `erh` join `Users` `uh` on((`uh`.`Id` = `erh`.`ResourceId`))) where ((`erh`.`ParentId` = `e`.`Id`) and (`erh`.`RoleCode` = 'Home AMP')) limit 1),'') AS `HomeAmp`,coalesce((select concat(`ur`.`LastName`,', ',`ur`.`FirstName`) from (`EngagementResources` `erh` join `Users` `ur` on((`ur`.`Id` = `erh`.`ResourceId`))) where ((`erh`.`ParentId` = `e`.`Id`) and (`erh`.`RoleCode` = 'Referral')) limit 1),'') AS `Referral`,(coalesce((select `i`.`Balance` from `Invoices` `i` where (`i`.`ExternalInvoiceId` = `b`.`ExternalInvoiceId`)),1.00) = 0) AS `Paid`,coalesce((select `i`.`Balance` from `Invoices` `i` where (`i`.`ExternalInvoiceId` = `b`.`ExternalInvoiceId`)),(`b`.`ServicesAmount` + `b`.`ExpensesAmount`)) AS `Balance` from (((`BillingRequests` `b` join `Engagements` `e` on((`e`.`Id` = `b`.`EngagementId`))) join `Clients` `c` on((`c`.`Id` = `e`.`ParentId`))) join `Users` `u` on((`u`.`Id` = `b`.`ResourceId`)));

